-- Originally generated by nwg-displays on 2026-05-14 at 14:39:16.
-- Edited by hand since: nwg-displays had picked conservative modes
-- (the MSI at 60Hz instead of 144, the BenQ at 1440p instead of 4K).
-- Re-running nwg-displays will overwrite this file.

-- BenQ EW2780U — 4K panel. scale 1.5 divides evenly (3840/1.5 = 2560,
-- 2160/1.5 = 1440), so the logical size matches the MSI and the
-- positions below still tile without gaps or overlap.
hl.monitor({ output = "DP-3",     mode = "3840x2160@60.00",  position = "2560x0", scale = 1.5 })

-- MSI G27CQ4 — a 144Hz panel held at 60Hz, deliberately.
--
-- Tested 2026-08-14: both 143.97Hz and 120Hz blank for 1-2s at a time as the
-- link drops and retrains. 120Hz needs ~13 Gbps, so this HDMI link is running
-- at HDMI 1.4 class (~8.2 Gbps usable), not 2.0 — the RX 9070 does HDMI 2.1,
-- so the limit is the cable or the monitor's HDMI port. At 1440p that leaves
-- 60Hz as the ceiling; even 85Hz would need ~9.4 Gbps.
--
-- To actually get 144/165Hz: move this monitor to DisplayPort. The G27CQ4 has
-- DP 1.2a (1440p@165 ≈ 14.5 Gbps, fits) and DP-1 and DP-2 on the GPU are free.
-- A certified Premium High Speed (18 Gbps) HDMI cable would only buy 120Hz.
hl.monitor({ output = "HDMI-A-1", mode = "2560x1440@59.95",  position = "0x0",    scale = 1.0 })
